<script setup lang="ts">
const props=defineProps<{items:{id:string;label:string}[];label:string;loading?:string;disabled?:boolean;dense?:boolean}>()
const selected=defineModel<string>({required:true})
function choose(id:string){if(!props.disabled&&props.items.some(item=>item.id===id))selected.value=id}
</script>
<template><view class="asset-tabs" :class="{dense}" role="tablist" :aria-label="label"><button v-for="item in items" :key="item.id" role="tab" :aria-selected="selected===item.id" :aria-busy="loading===item.id" :disabled="disabled" :class="{active:selected===item.id,loading:loading===item.id}" @click="choose(item.id)">{{item.label}}</button></view></template>
<style scoped>.asset-tabs{display:flex;flex-shrink:0;gap:24px;padding:0 var(--client-page-gutter, 10px) 0}.asset-tabs button{position:relative;flex:1;min-width:0;height:46px;margin:0;padding:0;border:0;background:transparent;color:var(--client-muted,#718198);font:inherit;font-size:15px;line-height:46px;white-space:nowrap}.asset-tabs button::after{border:0}.asset-tabs button.active{font-weight:600;color:var(--client-primary,#3479f6)}.asset-tabs button.active::before{content:'';position:absolute;left:50%;bottom:1px;transform:translateX(-50%);width:26px;height:3px;border-radius:2px;background:currentColor}.asset-tabs.dense{gap:4px;padding:0 var(--client-page-gutter, 10px) 0}.asset-tabs.dense button{font-size:13px}.asset-tabs button.loading::before{animation:asset-tab-loading .8s ease-in-out infinite alternate}@keyframes asset-tab-loading{from{opacity:.3;transform:translateX(-50%) scaleX(.4)}to{opacity:1;transform:translateX(-50%) scaleX(1)}}@media(prefers-reduced-motion:reduce){.asset-tabs button.loading::before{animation:none;opacity:.6}}</style>
